  // can freeze the orb on shot 1, then clear the mint patch across shots 2-3
  // exactly as freezeDuration ticks out. Stays in force on every replay too.
  forcedOpeningQueue: ["mint", "mint", "mint", "grass"],
  ftueFreezeDemo: true,
